con = sqlite3.connect(DB_PATH)
updated = 0
skipped = 0

for slug, name, description, field in UPDATES:
    cur = con.execute(
        "UPDATE dictionaries SET name=?, description=?, field=? WHERE slug=?",
        (name, description, field, slug),
    )
    if cur.rowcount:
        print(f"  OK  {slug}: {name}")
        updated += 1
    else:
        print(f"  --  {slug} (not found)")
        skipped += 1

con.commit()
con.close()

print(f"\nDone: {updated} updated, {skipped} not found.")
